mapper.delete:
/* 
 * isry.couns.cmmn.mapper.CounsMapper.deleteCnsltntAsgn : (게시판 공통) 상담자 할당 Delete
 * 2023.06.02 추가 - Jeong.Won.Je
 */
    DELETE
    FROM    AYA150
    WHERE   1=1
    AND     BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}
    AND     BBSCTT_TYPE_SE_CD   =   #{BBSCTT_TYPE_SE_CD}

mapper.update:
    /* 
     * isry.couns.cmmn.mapper.CounsMapper.updateEmlSndngYN : (게시판 공통) 이메일발송여부 = 'Y' 업데이트
     * 2023.06.05 추가 - Jeong.Won.Je
     */
		UPDATE
		      AYE100
		SET   
		      EML_SNDNG_YN        =   'Y'
		      , LAST_MDFR_ID      =   #{loginId}
		      , LAST_MDFCN_DT     =   SYSDATE
		WHERE 1=1
		AND   BBSCTT_ESNTAL_NO    =   #{BBSCTT_ESNTAL_NO}
		AND   BBSCTT_TYPE_SE_CD   =   #{BBSCTT_TYPE_SE_CD}
